#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    vector<long long> a(n);
    for (auto &x : a) scanf("%lld", &x);
    // left[i]: non-decreasing run ending at i; right[i]: run starting at i.
    vector<int> left(n, 1), right(n, 1);
    for (int i = 1; i < n; i++)
        if (a[i - 1] <= a[i]) left[i] = left[i - 1] + 1;
    for (int i = n - 2; i >= 0; i--)
        if (a[i] <= a[i + 1]) right[i] = right[i + 1] + 1;
    int answer = *max_element(left.begin(), left.end());
    for (int i = 0; i < n; i++) {
        int l = i ? left[i - 1] : 0, r = i + 1 < n ? right[i + 1] : 0;
        answer = max({answer, l + 1, r + 1});
        // Changing a[i] can bridge both runs when a[i-1] <= a[i+1].
        if (i > 0 && i < n - 1 && a[i - 1] <= a[i + 1]) answer = max(answer, l + r + 1);
    }
    printf("%d\n", answer);
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken();
        int n = (int) st.nval;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) { st.nextToken(); a[i] = (long) st.nval; }
        // left[i]: non-decreasing run ending at i; right[i]: run starting at i.
        int[] left = new int[n], right = new int[n];
        int answer = 0;
        for (int i = 0; i < n; i++) {
            left[i] = i > 0 && a[i - 1] <= a[i] ? left[i - 1] + 1 : 1;
            answer = Math.max(answer, left[i]);
        }
        for (int i = n - 1; i >= 0; i--) right[i] = i + 1 < n && a[i] <= a[i + 1] ? right[i + 1] + 1 : 1;
        for (int i = 0; i < n; i++) {
            int l = i > 0 ? left[i - 1] : 0, r = i + 1 < n ? right[i + 1] : 0;
            answer = Math.max(answer, Math.max(l + 1, r + 1));
            // Changing a[i] can bridge both runs when a[i-1] <= a[i+1].
            if (i > 0 && i < n - 1 && a[i - 1] <= a[i + 1]) answer = Math.max(answer, l + r + 1);
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	n := nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	// left[i]: non-decreasing run ending at i; right[i]: run starting at i.
	left := make([]int, n)
	right := make([]int, n)
	answer := 0
	for i := 0; i < n; i++ {
		left[i] = 1
		if i > 0 && a[i-1] <= a[i] {
			left[i] = left[i-1] + 1
		}
		answer = max(answer, left[i])
	}
	for i := n - 1; i >= 0; i-- {
		right[i] = 1
		if i+1 < n && a[i] <= a[i+1] {
			right[i] = right[i+1] + 1
		}
	}
	for i := 0; i < n; i++ {
		l, r := 0, 0
		if i > 0 {
			l = left[i-1]
		}
		if i+1 < n {
			r = right[i+1]
		}
		answer = max(answer, l+1, r+1)
		// Changing a[i] can bridge both runs when a[i-1] <= a[i+1].
		if i > 0 && i < n-1 && a[i-1] <= a[i+1] {
			answer = max(answer, l+r+1)
		}
	}
	fmt.Println(answer)
}
